def countCharacters(words, chars):
    # Count frequency of each character in chars
    chars_count = [0] * 26
    for c in chars:
        chars_count[ord(c) - ord('a')] += 1

    result = 0

    for word in words:
        word_count = [0] * 26
        for c in word:
            word_count[ord(c) - ord('a')] += 1

        # Check that word can be formed by chars
        can_form = True
        for i in range(26):
            if word_count[i] > chars_count[i]:
                can_form = False
                break

        if can_form:
            result += len(word)

    return result
